-- The site assistant learns what visitors ask and what competitors answer (competitor report, 2026-11-27):
-- licence number and how to check it, men and women, university vs institute, why Alsmow, jobs and limits of each
-- diploma (law ≠ a lawyer licence, nursing management ≠ a nursing licence), towns around Hafr, programmes not offered.
-- Appended to settings › المساعد الذكي › قاعدة المعرفة (edited or removed from the dashboard); an entry whose
-- question is already there is skipped. {contact} in an answer becomes the phone / WhatsApp lines.
INSERT INTO settings (k, v) SELECT 'assistant', JSON_OBJECT('kb', JSON_ARRAY()) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM settings WHERE k = 'assistant');
UPDATE settings SET v = JSON_SET(v, '$.kb', JSON_ARRAY()) WHERE k = 'assistant' AND (JSON_EXTRACT(v, '$.kb') IS NULL OR JSON_TYPE(JSON_EXTRACT(v, '$.kb')) <> 'ARRAY');
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'هل المعهد للرجال أم للنساء؟', 'variants', JSON_ARRAY('المعهد للبنات بس', 'المعهد للنساء فقط', 'فيه قسم رجال', 'فيه قسم نسائي', 'معهد نسائي في حفر الباطن', 'يقبل شباب', 'للشباب ولا للبنات', 'مختلط', 'معهد للرجال في حفر الباطن'), 'a', '**معهد السمو للرجال والنساء** 🌿\n- **معهد السمو المتخصص العالي للتدريب** مرخّص من المؤسسة العامة للتدريب التقني والمهني للجنسين، ويقدّم الدبلومات والدورات.\n- **معهد السمو المتخصص للغات** مخصّص للنساء.\nمواعيد كل فئة وتفاصيل الأقسام يوضحها فريق القبول:\n{contact}', 'link', NULL)) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'هل المعهد للرجال أم للنساء؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'ما رقم ترخيص المعهد وكيف أتحقق منه؟', 'variants', JSON_ARRAY('رقم الترخيص', 'رقم ترخيص المعهد', 'رقم المنشأة', 'المعهد مرخص', 'المعهد رسمي', 'المعهد نظامي', 'التحقق من ترخيص السمو', 'هل السمو معتمد', 'هل المعهد معتمد من التقني'), 'a', 'نعم، المعهد مرخّص من **المؤسسة العامة للتدريب التقني والمهني** 🌿\n- **معهد السمو المتخصص العالي للتدريب:** رقم المنشأة **5173375061812** (معهد تدريب عالي، يحق له تقديم الدبلومات).\n- **معهد السمو المتخصص للغات:** رقم المنشأة **951000071**.\nتحقّق بنفسك: صفحة «الاستعلام عن المعاهد المرخّصة» في موقع المؤسسة: https://pt-web.tvtc.gov.sa/institutes\nاختر المنطقة الشرقية ← حفر الباطن، وافتح بطاقة المعهد لترى خططه التدريبية المعتمدة.', 'link', '/blog/هل-دبلومات-معهد-السمو-معتمدة')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'ما رقم ترخيص المعهد وكيف أتحقق منه؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'هل دبلومات معهد السمو معتمدة؟', 'variants', JSON_ARRAY('الدبلوم معتمد', 'هل الدبلوم معتمد', 'الدبلومات معتمده', 'الشهادة معتمدة', 'معترف فيها', 'معتمد من التقني', 'معتمدة من المؤسسة', 'الشهاده رسميه', 'الدبلوم معترف فيه'), 'a', 'نعم 🌿 كل دبلومات المعهد **خطط تدريبية معتمدة** لدى المؤسسة العامة للتدريب التقني والمهني ومسجّلة في منظومة التدريب الأهلي: إدارة التمريض، إدارة المستشفيات والخدمات الصحية، القانون، الذكاء الاصطناعي، الموارد البشرية (حضوري وعن بُعد)، والإدارة المكتبية.\nوبعض البرامج **مصنّفة من وزارة الموارد البشرية**، مثل دبلوم القانون ودبلوم الموارد البشرية عن بُعد.\nرقم منشأة المعهد لدى المؤسسة: 5173375061812.', 'link', '/blog/هل-دبلومات-معهد-السمو-معتمدة')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'هل دبلومات معهد السمو معتمدة؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'جامعة ولا معهد بعد الثانوي؟', 'variants', JSON_ARRAY('الجامعة او المعهد', 'ايهما افضل الجامعة ولا المعهد', 'ما انقبلت في الجامعة', 'ادخل جامعة ولا دبلوم', 'بعد الثانوي وش ادرس', 'متردد بين الجامعة والمعهد', 'ما قبلوني بالجامعة'), 'a', 'سؤال مهم 🌿 باختصار:\n- **الجامعة:** حوالي 4 سنوات، نسب موزونة وقدرات ومقاعد محدودة، وتناسب الوظائف التي تشترط البكالوريوس.\n- **الدبلوم المعتمد:** حوالي سنتين ونصف (8 مستويات)، تطبيقي ومرتبط بوظيفة واضحة، والقبول أسهل وأمرن (حضوري أو عن بُعد).\nإذا لم تُقبل في التخصص الذي تريده، أو تريد دخول سوق العمل أسرع، فالدبلوم المعتمد خيار ذكي، وبعض الجامعات تتيح التجسير بعده حسب شروطها.\nأخبرني بمجالك المفضّل (صحة، قانون، تقنية، إدارة…) وأرشّح لك دبلومًا.', 'link', '/blog/جامعة-ام-معهد-بعد-الثانوي')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'جامعة ولا معهد بعد الثانوي؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'ليش أختار معهد السمو؟', 'variants', JSON_ARRAY('وش يميزكم', 'ايش يميز المعهد', 'الفرق بينكم وبين المعاهد الثانية', 'افضل معهد في حفر الباطن', 'ليش السمو', 'مميزات المعهد', 'ليه اسجل عندكم', 'ليش اختاركم'), 'a', '🌿 ما يميّز **معهد السمو**:\n- **دبلومات نادرة في حفر الباطن:** القانون، والذكاء الاصطناعي، وإدارة التمريض، وإدارة المستشفيات، وقليل جدًا من المعاهد في المدينة يقدّمها.\n- **معهد تدريب عالي مرخّص** من المؤسسة العامة للتدريب التقني والمهني (رقم المنشأة 5173375061812)، وكل دبلوم خطة معتمدة.\n- **للرجال والنساء**، ومعهد لغات للنساء.\n- **حضوري في حفر الباطن، وبرامج عن بُعد** لمن يسكن خارجها أو يعمل.\n- عروض معلنة على بعض البرامج (اسألني «فيه خصم؟»).\nوقبل التسجيل في أي معهد، اسأله 8 أسئلة جمعناها لك في هذا الدليل:', 'link', '/blog/افضل-معهد-في-حفر-الباطن')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'ليش أختار معهد السمو؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'هل أصير محامي بعد دبلوم القانون؟', 'variants', JSON_ARRAY('اصير محامي', 'اصير محاميه', 'رخصة محاماة', 'اشتغل محامي', 'دبلوم القانون يخليني محامي', 'افتح مكتب محاماة', 'مستشار قانوني'), 'a', 'صراحةً: **مزاولة المحاماة** لها شروط من وزارة العدل، منها المؤهل الجامعي في الشريعة أو القانون ثم الرخصة، فالدبلوم وحده لا يمنح رخصة محاماة.\nلكن **دبلوم القانون** يفتح لك وظائف مطلوبة: مساعد أو باحث قانوني، صياغة ومراجعة العقود، الشؤون القانونية وشؤون الموظفين في الشركات، والعمل مساعدًا في مكاتب المحاماة.\nومن مميزاته أنه **يقبل استكمال البكالوريوس** (حسب شروط الجامعة)، فيكون خطوتك الأولى نحو المحاماة.', 'link', '/programs/دبلوم-القانون')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'هل أصير محامي بعد دبلوم القانون؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'من يناسبه دبلوم إدارة التمريض؟', 'variants', JSON_ARRAY('دبلوم التمريض لمين', 'لازم اكون ممرض', 'لازم اكون ممرضه', 'يقبل غير الممرضين', 'شروط دبلوم التمريض', 'دبلوم التمريض يعطيني تصنيف', 'اشتغل ممرضه بعد الدبلوم'), 'a', '**دبلوم إدارة التمريض** دبلوم **إداري وقيادي**: التخطيط والتنظيم في أقسام التمريض، وتوزيع المناوبات، وتقييم الأداء، والجودة وسلامة المرضى.\n- يناسب الكوادر التمريضية التي تريد الانتقال إلى الإشراف والقيادة، ومن يريد العمل الإداري في القطاع الصحي.\n- **تنبيه مهم:** الدبلوم لا يمنح ترخيص ممارسة التمريض؛ الممارسة تتطلب تصنيف **الهيئة السعودية للتخصصات الصحية**.\nشروط القبول (المؤهل والخبرة) يوضحها فريق القبول:\n{contact}', 'link', '/programs/دبلوم-إدارة-التمريض')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'من يناسبه دبلوم إدارة التمريض؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'ما الفرق بين دبلوم إدارة المستشفيات ودبلوم إدارة التمريض؟', 'variants', JSON_ARRAY('الفرق بين التمريض والمستشفيات', 'ادارة المستشفيات ولا ادارة التمريض', 'ايهما افضل التمريض او المستشفيات', 'الدبلومات الصحية'), 'a', 'الاثنان 8 مستويات ومعتمدان، والفرق في المسار:\n- **إدارة المستشفيات والخدمات الصحية:** العمل الإداري في المنشأة الصحية كلها: القبول والمواعيد، السجلات، الجودة، تنظيم الأقسام. **لا يشترط** أن تكون ممارسًا صحيًا.\n- **إدارة التمريض:** القيادة والإشراف **داخل أقسام التمريض** تحديدًا: المناوبات، تقييم الكوادر، سلامة المرضى. يناسب الكوادر التمريضية أكثر.\nأخبرني بخلفيتك وأرشّح لك الأنسب.', 'link', NULL)) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'ما الفرق بين دبلوم إدارة المستشفيات ودبلوم إدارة التمريض؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'ما الفرق بين دبلوم الموارد البشرية الحضوري وعن بعد؟', 'variants', JSON_ARRAY('الموارد البشرية حضوري ولا عن بعد', 'الفرق بين الحضوري والاونلاين', 'موارد بشرية اونلاين', 'ايهما افضل حضوري او عن بعد'), 'a', 'الاثنان دبلوم **إدارة الموارد البشرية** المعتمد، والفرق في طريقة الدراسة:\n- **الحضوري:** في مقر المعهد بحفر الباطن.\n- **عن بُعد:** محاضرات مباشرة من بيتك، مناسب للموظفين ومن يسكن خارج حفر الباطن، وعليه **عرض خاص** حاليًا، ومن مميزاته المعلنة أنه **مصنّف من وزارة الموارد البشرية** و**ساعاته تعادل نقطتين في الترقيات**.\nاكتب «الموارد البشرية عن بعد» أو «الموارد البشرية حضوري» لأعرض لك تفاصيل كل واحد.', 'link', NULL)) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'ما الفرق بين دبلوم الموارد البشرية الحضوري وعن بعد؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'هل الدبلوم يفيد في الترقية الوظيفية؟', 'variants', JSON_ARRAY('ترقية', 'نقاط الترقية', 'يحسب في الترقيه', 'الدبلوم للموظفين', 'موظف حكومي وابغى دبلوم', 'يرفع راتبي', 'نقطتين في الترقيات'), 'a', 'للموظفين 🌿 بعض برامجنا معلن عنها أنها **مصنّفة من وزارة الموارد البشرية**، ودبلوم **الموارد البشرية عن بُعد** ساعاته **تعادل نقطتين في الترقيات** حسب بيانات البرنامج.\nأما احتساب الدبلوم في ترقيتك أنت فيعود لأنظمة جهة عملك، فتأكد منها، ويسعدنا تزويدك بإفادة أو تفاصيل البرنامج:\n{contact}', 'link', '/programs/ادارة-الموارد-البشرية-عن-بعد')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'هل الدبلوم يفيد في الترقية الوظيفية؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'كم مدة الدبلوم في المعهد؟', 'variants', JSON_ARRAY('مدة الدبلومات', 'الدبلوم كم سنة', 'كم سنه الدبلوم', 'كم مستوى', 'وش يعني ثمانية مستويات', 'مدة الدورات'), 'a', '- **الدبلومات:** 8 مستويات تدريبية، أي **سنتان ونصف تقريبًا** (كل مستوى فصل تدريبي).\n- **الدورات التأهيلية:** من **3 إلى 6 أشهر** (مثل الحاسب الآلي، وإدخال البيانات، والإدارة المكتبية).\nاكتب اسم البرنامج لأعطيك مدته وساعاته بالضبط.', 'link', '/programs')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'كم مدة الدبلوم في المعهد؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'أنا من خارج حفر الباطن، هل أستطيع الدراسة عندكم؟', 'variants', JSON_ARRAY('انا من القيصومة', 'انا من رفحاء', 'انا من النعيرية', 'انا من قرية العليا', 'ساكن بعيد', 'من مدينه ثانيه', 'من الدمام', 'من الرياض', 'اقدر ادرس من مدينتي', 'فروعكم'), 'a', 'أكيد 🌿\n- **عن بُعد:** في البرامج المتاحة عن بُعد (مثل دبلوم الموارد البشرية عن بُعد) تدرس من بيتك في أي مدينة.\n- **حضوري:** في حفر الباطن، وكثير من متدربينا من القيصومة والنعيرية ورفحاء وقرية العليا.\n- **فروع قادمة:** الدمام، الرياض، المدينة المنورة، خميس مشيط.\nأخبرني بالبرنامج الذي يهمك لأخبرك بطريقة دراسته.', 'link', '/blog/دبلومات-معتمدة-القيصومة-النعيرية-رفحاء-قرية-العليا')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'أنا من خارج حفر الباطن، هل أستطيع الدراسة عندكم؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'هل الذكاء الاصطناعي صعب أو يحتاج برمجة؟', 'variants', JSON_ARRAY('لازم اعرف برمجة', 'الذكاء الاصطناعي صعب', 'مبتدئ في الذكاء الاصطناعي', 'ما اعرف كمبيوتر كثير', 'وش ادرس في الذكاء الاصطناعي'), 'a', 'برنامج **الذكاء الاصطناعي** يبدأ معك من **المفاهيم الأساسية**: ما هو الذكاء الاصطناعي، والتعلّم الآلي (Machine Learning)، والتعلّم العميق (Deep Learning)، وكيف تستخدم أدواته في العمل. 74 ساعة معتمدة.\nوعليه حاليًا **خصم 25% لأول 100 متدرب**.\nمستوى المتطلبات المسبقة يوضحه فريق القبول حسب خلفيتك:\n{contact}', 'link', '/programs/الذكاء-الاصطناعي')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'هل الذكاء الاصطناعي صعب أو يحتاج برمجة؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'هل عندكم دبلوم أمن سيبراني أو محاسبة أو تصميم؟', 'variants', JSON_ARRAY('امن سيبراني', 'دبلوم محاسبة', 'تصميم داخلي', 'تصميم جرافيك', 'برمجة', 'شبكات', 'تسويق', 'سلامة مهنية', 'دبلوم تجميل', 'دبلوم محاسبه'), 'a', 'حاليًا لا 🌿 دبلومات المعهد المتاحة: **إدارة التمريض، إدارة المستشفيات والخدمات الصحية، القانون، الذكاء الاصطناعي، الموارد البشرية (حضوري وعن بُعد)، الإدارة المكتبية**، ودورات في الحاسب الآلي وإدخال البيانات والإدارة المكتبية والإنجليزية.\nإن كان القريب من اهتمامك التقنية فدبلوم **الذكاء الاصطناعي** هو الأقرب. ولمعرفة البرامج القادمة:\n{contact}', 'link', '/programs')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'هل عندكم دبلوم أمن سيبراني أو محاسبة أو تصميم؟', NULL, '$.kb[*].q') IS NULL;
UPDATE settings SET v = JSON_ARRAY_APPEND(v, '$.kb', JSON_OBJECT('q', 'كيف أبدأ التسجيل الآن؟', 'variants', JSON_ARRAY('ابغى اسجل', 'ابي اسجل الحين', 'خطوات التسجيل', 'احجز مقعد', 'سجلوني', 'كيف احجز'), 'a', 'ثلاث خطوات بسيطة 🌿\n1. اختر البرنامج (أو اسألني أرشّح لك).\n2. عبّئ نموذج التسجيل في الموقع، أو راسلنا واتساب باسم البرنامج.\n3. يتواصل معك فريق القبول لإكمال الإجراءات وتأكيد موعد البداية.\n{contact}', 'link', '/register')) WHERE k = 'assistant' AND JSON_SEARCH(v, 'one', 'كيف أبدأ التسجيل الآن؟', NULL, '$.kb[*].q') IS NULL;
